title = "Reserve Transfer Tax"
intent = "3% of every transfer goes to the reserve to strengthen the crown and fund commons restoration."
def on_transfer(src, dst, item, qty):
    if src == "reserve" or dst == "reserve":
        return 0
    return qty * 0.03

